<script setup lang="ts">
import type { Product } from '../shared'
import { ArrowLeft, LockKeyhole } from 'lucide-vue-next'
import { formatPrice } from '../shared'
const { items } = useCart()
const { data: products } = await useFetch<Product[]>('/api/products')
const lines = computed(() => items.value.map(i => ({ ...i, product: products.value?.find(p => p.id === i.id) })).filter(i => i.product))
const total = computed(() => lines.value.reduce((s: number,i: { product?: Product; quantity: number }) => s + i.product!.price * i.quantity, 0))
const form = reactive({ name: '', mobile: '', city: '', address: '', postalCode: '' })
const loading = ref(false), error = ref('')
async function submit() {
  error.value = ''; loading.value = true
  try {
    const result = await $fetch<{paymentUrl:string}>('/api/orders', { method: 'POST', body: { ...form, items: items.value } })
    window.location.assign(result.paymentUrl)
  } catch (e: any) { error.value = e?.data?.statusMessage || 'ثبت سفارش انجام نشد. دوباره تلاش کنید.' }
  finally { loading.value = false }
}
useSeoMeta({ title: 'تکمیل سفارش | پیله پاتری' })
</script>
<template><div class="container checkout-page"><div class="page-header"><span class="eyebrow">CHECKOUT</span><h1>تکمیل سفارش</h1><p>یک قدم تا رسیدن سفال‌های دوست‌داشتنی‌تان.</p></div><div v-if="!lines.length" class="empty-state"><h2>سبد خرید شما خالی است</h2><NuxtLink to="/products" class="btn">دیدن محصولات <ArrowLeft :size="16"/></NuxtLink></div><div v-else class="checkout-grid"><form class="checkout-form" @submit.prevent="submit"><h2>مشخصات دریافت‌کننده</h2><div class="field-grid"><label class="form-field">نام و نام خانوادگی <input v-model="form.name" required minlength="2" maxlength="100" placeholder="نام شما" autocomplete="name"/></label><label class="form-field">شماره موبایل <input v-model="form.mobile" required pattern="09[0-9]{9}" inputmode="tel" dir="ltr" placeholder="09123456789" autocomplete="tel"/></label><label class="form-field">شهر <input v-model="form.city" required maxlength="100" placeholder="شهر محل سکونت" autocomplete="address-level2"/></label><label class="form-field">کد پستی <input v-model="form.postalCode" maxlength="20" inputmode="numeric" dir="ltr" placeholder="اختیاری" autocomplete="postal-code"/></label><label class="form-field full">آدرس کامل <textarea v-model="form.address" required minlength="10" maxlength="500" placeholder="خیابان، کوچه، پلاک و واحد" autocomplete="street-address"/></label></div><p v-if="error" class="error-msg">{{ error }}</p><button class="btn pay-button" :disabled="loading">{{ loading ? 'در حال اتصال به درگاه...' : 'ثبت سفارش و پرداخت' }} <ArrowLeft v-if="!loading" :size="17"/></button><p class="secure-note"><LockKeyhole :size="15"/> پرداخت از طریق درگاه امن زرین‌پال انجام می‌شود.</p></form><aside class="order-recap"><h2>سفارش شما</h2><div v-for="line in lines" :key="line.id" class="recap-item"><img :src="line.product!.image" :alt="line.product!.name"/><div><strong>{{ line.product!.name }}</strong><small>تعداد: {{ line.quantity }}</small></div><span>{{ formatPrice(line.product!.price*line.quantity) }}</span></div><div class="recap-total"><span>مبلغ قابل پرداخت</span><strong>{{ formatPrice(total) }} تومان</strong></div><p>هزینه‌ی ارسال پس از هماهنگی مشخص می‌شود.</p></aside></div></div></template>
<style scoped>.checkout-page{padding-bottom:110px}.checkout-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:80px}.checkout-form h2,.order-recap h2{font-weight:500;font-size:20px;margin:0 0 30px}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:23px}.field-grid .full{grid-column:span 2}.checkout-form .error-msg{margin-top:20px}.pay-button{margin-top:28px;min-width:245px}.secure-note{font-size:11px;color:var(--muted);display:flex;gap:8px;align-items:center}.order-recap{background:#e9ebea;padding:30px;height:max-content}.recap-item{display:flex;align-items:center;gap:13px;border-bottom:1px solid #d4d2c7;padding:13px 0}.recap-item img{width:56px;height:60px;object-fit:cover}.recap-item div{display:flex;flex-direction:column;gap:5px}.recap-item strong{font-size:12px;font-weight:500}.recap-item small{font-size:11px;color:var(--muted)}.recap-item>span{font-size:11px;margin-right:auto;white-space:nowrap}.recap-total{display:flex;justify-content:space-between;margin-top:25px;font-size:13px}.recap-total strong{font-size:15px}.order-recap p{font-size:11px;color:var(--muted);margin-top:22px}@media(max-width:750px){.checkout-grid{gap:35px}}@media(max-width:650px){.checkout-page{padding-bottom:65px}.checkout-grid{grid-template-columns:1fr}.field-grid{gap:15px}.pay-button{width:100%}}</style>
